const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=x=>JSON.stringify(x??null,null,2);
const labels={experience:'经历',story:'故事／高光',fragment:'片段',topic:'能力主题',belongs_to:'归属经历',about_topic:'关联主题'};
const empty='<div class="index-empty">这一类目前没有记录。先在经历库录入资料，索引会自动更新。</div>';

export function indexSidebar(index,kind){if(!index)return '<p class="muted">正在读取索引…</p>';const count=x=>index.nodes.filter(n=>n.kind===x).length;return `<div class="side-title">当前 Wiki 快照</div><p class="muted">第 ${index.revision} 版 · ${index.nodes.length} 节点<br>${index.relations.length} 关系 · ${index.sources.length} 来源</p><button class="side-item ${kind==='all'?'active':''}" data-index-kind="all">全部节点 <em>${index.nodes.length}</em></button>${['experience','story','fragment','topic'].map(x=>`<button class="side-item ${kind===x?'active':''}" data-index-kind="${x}">${labels[x]} <em>${count(x)}</em></button>`).join('')}<div class="side-title">基础信息</div><button class="side-item" data-index-node="profile_local">个人信息 <em>${index.profile.saved?'已保存':'未录入'}</em></button><div class="side-title">索引说明</div><p class="muted">检索候选是完整经历。故事、片段和主题只给所属经历提供索引线索。</p>`}

export function indexWorkspace(index,pane,kind){if(!index)return '<div class="index-empty">正在读取索引…</div>';const tabs=`<div class="compare-controls"><b>第 ${index.revision} 版索引</b>${[['nodes','节点'],['relations','关系'],['search','检索']].map(([id,name])=>`<button data-index-pane="${id}" class="${pane===id?'active':''}">${name}</button>`).join('')}<button data-action="index-refresh">刷新快照</button></div>`;let body='';if(pane==='nodes'){const nodes=index.nodes.filter(n=>kind==='all'||n.kind===kind);body=nodes.length?`<table class="index-table"><thead><tr><th>节点</th><th>ID / 类型</th><th>所属经历</th><th>状态</th><th>来源 / 关系</th></tr></thead><tbody>${nodes.map(n=>`<tr data-index-node="${esc(n.id)}"><td><strong>${esc(n.title)}</strong><small>${esc(n.summary)}</small></td><td><code>${esc(n.id)}</code><small>${esc(labels[n.kind]||n.kind)}</small></td><td>${esc(n.experience_id||'—')}</td><td>${esc(n.status)}</td><td>${n.source_ids.length} / ${n.incoming_relation_ids.length+n.outgoing_relation_ids.length}</td></tr>`).join('')}</tbody></table>`:empty}
if(pane==='relations'){body=index.relations.length?`<table class="index-table"><thead><tr><th>关系</th><th>起点</th><th>终点</th><th>状态 / 来源</th></tr></thead><tbody>${index.relations.map(r=>`<tr data-index-relation="${esc(r.id)}"><td><strong>${esc(labels[r.type]||r.type)}</strong><small><code>${esc(r.id)}</code></small></td><td>${esc(r.from_title)}<small><code>${esc(r.from_id)}</code></small></td><td>${esc(r.to_title)}<small><code>${esc(r.to_id)}</code></small></td><td>${esc(r.status)} · ${r.source_ids.length}</td></tr>`).join('')}</tbody></table>`:empty}
if(pane==='search'){const records=index.experience_search;body=`<div class="index-search"><label class="field"><span>测试索引词：使用与正式 JD 检索相同的索引文本</span><input id="index-term" value="${esc(index.query)}" placeholder="例如 RAG、Excel、用户需求"></label><button class="primary" data-action="index-search">检索经历</button><p class="muted">${index.query?`「${esc(index.query)}」命中 ${index.matches.length} 段经历`:'输入一个词后可看到命中的经历与具体索引字段。'}</p></div>${records.length?`<div class="index-records">${records.map(r=>`<article class="index-record"><h3><button data-index-node="${esc(r.experience_id)}">${esc(r.title)}</button> <small>${esc(r.experience_type)}</small></h3><p class="muted">Experience ID：<code>${esc(r.experience_id)}</code> · ${r.parts.length} 个索引字段</p>${index.query?`<p>${r.matched_parts.length?'命中：':'未命中'}</p>${r.matched_parts.map(part=>`<div class="link"><code>${esc(part.node_id)}</code> · ${esc(part.field)}<small>${esc(part.text)}</small></div>`).join('')}`:`<details><summary>查看索引组成</summary>${r.parts.map(part=>`<div class="link"><code>${esc(part.node_id)}</code> · ${esc(part.field)}<small>${esc(part.text)}</small></div>`).join('')}</details>`}</article>`).join('')}</div>`:empty}`}
return tabs+body}

export function indexInspector(index,selection,document){if(!index)return '<p class="muted">正在读取索引…</p>';if(!selection)return `<h2 class="panel-title">索引详情</h2><p class="muted">点击节点或关系，查看它的归属、来源及正文。</p><p class="notice">当前真实资料库：${index.nodes.length} 个节点、${index.relations.length} 条关系。页面原型里的示例节点不计入这里。</p>`;if(selection.kind==='profile'){return `<h2 class="panel-title">个人信息</h2><p class="muted">基础信息单独存储；当前${index.profile.saved?'已保存':'未录入'}。它不是 Experience 检索候选。</p><pre class="json">${esc(pretty(index.profile))}</pre><h3>Markdown</h3><pre class="json">${esc(document||'暂无正文')}</pre>`}
if(selection.kind==='node'){const n=index.nodes.find(x=>x.id===selection.id);if(!n)return '<p class="muted">节点已不存在，请刷新索引。</p>';const refs=n.source_ids.map(id=>index.sources.find(s=>s.id===id)).filter(Boolean),rels=index.relations.filter(r=>r.from_id===n.id||r.to_id===n.id);return `<h2 class="panel-title">${esc(n.title)}</h2><span class="chip">${esc(labels[n.kind]||n.kind)}</span><p class="muted"><code>${esc(n.id)}</code></p><div class="section"><h3>节点索引字段</h3><pre class="json">${esc(pretty(n))}</pre></div><div class="section"><h3>连接关系 · ${rels.length}</h3>${rels.map(r=>`<button class="side-item" data-index-relation="${esc(r.id)}">${esc(labels[r.type]||r.type)} · ${esc(r.from_title)} → ${esc(r.to_title)}</button>`).join('')||'<p class="muted">暂无连接</p>'}</div><div class="section"><h3>来源引用 · ${refs.length}</h3>${refs.map(s=>`<button class="side-item" data-index-source="${esc(s.id)}">${esc(s.id)} · ${esc(s.quote.slice(0,65))}</button>`).join('')||'<p class="muted">暂无来源</p>'}</div><div class="section"><h3>Markdown 正文</h3><pre class="json">${esc(document??'正在读取…')}</pre></div>`}
if(selection.kind==='relation'){const r=index.relations.find(x=>x.id===selection.id);if(!r)return '<p class="muted">关系已不存在，请刷新索引。</p>';return `<h2 class="panel-title">${esc(labels[r.type]||r.type)}</h2><p class="muted"><code>${esc(r.id)}</code></p><div class="section"><h3>端点</h3><button class="side-item" data-index-node="${esc(r.from_id)}">起点：${esc(r.from_title)} · ${esc(r.from_id)}</button><button class="side-item" data-index-node="${esc(r.to_id)}">终点：${esc(r.to_title)} · ${esc(r.to_id)}</button></div><div class="section"><h3>关系索引字段</h3><pre class="json">${esc(pretty(r))}</pre></div><div class="section"><h3>来源引用</h3>${r.source_ids.map(id=>`<button class="side-item" data-index-source="${esc(id)}">${esc(id)}</button>`).join('')||'<p class="muted">暂无来源</p>'}</div>`}
const s=index.sources.find(x=>x.id===selection.id);return s?`<h2 class="panel-title">来源引用</h2><pre class="json">${esc(pretty(s))}</pre>`:'<p class="muted">来源不存在</p>'}

